#include <stdio.h>
#include <stdlib.h>

int main() {
    void *p1 = malloc(10);  // Allocate first block
    void *p2 = malloc(10);  // Allocate second block
    if (p1 && p2) {
        free(p1);  // Free first block
        free(p2);  // Free second block, potentially coalescing with the first
        void *p3 = malloc(20);  // Attempt to allocate a larger block
        if (p3) {
            printf("Successfully allocated 20 bytes after coalescing\n");
            free(p3);
        } else {
            printf("Failed to allocate 20 bytes\n");
        }
    } else {
        printf("Initial allocations failed\n");
    }
    return 0;
}
